/* number in all three languages (decimal comma in FR/DE) */
const n3 = (v, d) => { const s = d == null ? String(v) : v.toFixed(d); return [s, s.replace('.', ','), s.replace('.', ',')]; };
const q3 = (tpl, vals) => [0, 1, 2].map(i => { let s = sxL(tpl, i); for (const k in vals) s = s.split('{' + k + '}').join(Array.isArray(vals[k]) ? vals[k][i] : vals[k]); return s; }).join('|');

